require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "admission shared by every company" do
  include_context "timekeeping entry writes"

  def create_command_for(company, generation:)
    project = timekeeping_arrange.project(company:)
    owner = timekeeping_arrange.user(company:, role: "owner")
    body = { "project_id" => project, "work_date" => "2026-03-02", "duration" => 60.0, "note" => "Planning",
             "source" => "manual", "source_metadata" => {} }
    build_entry_command(:create, token: timekeeping_arrange.token_for(owner), body:, generation:)
  end

  # "Give the Timekeeping application (`timekeeping/`) one stored admission state: it admits entry writes at
  # exactly one generation, or at none while fenced."
  # "After `admit!(generation: 4)`, a write carrying 4 succeeds and one carrying 3 is refused."
  it "applies one admitted generation to every company and keeps a single admission row however many companies write" do
    company_before = timekeeping_arrange.company
    Timekeeping::Admission.admit!(generation: 4)
    company_after = timekeeping_arrange.company

    [company_before, company_after].each do |company|
      admitted = described_class.new.call(create_command_for(company, generation: 4))
      stale = described_class.new.call(create_command_for(company, generation: 3))

      expect(admitted.status).to eq(201)
      expect([stale.status, JSON.parse(stale.body)]).to eq([409, { "reason" => "stale_generation" }])
    end

    expect(Entry.where(company_id: company_before).count).to eq(1)
    expect(Entry.where(company_id: company_after).count).to eq(1)
    expect(Timekeeping::Admission.count).to eq(1)
    expect(Timekeeping::Admission.current.generation).to eq(4)
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "fence shared by every company" do
  include_context "timekeeping entry writes"

  def fenced_create_for(company, generation:)
    project = timekeeping_arrange.project(company:)
    owner = timekeeping_arrange.user(company:, role: "owner")
    body = { "project_id" => project, "work_date" => "2026-03-02", "duration" => 60.0, "note" => "Planning",
             "source" => "manual", "source_metadata" => {} }
    build_entry_command(:create, token: timekeeping_arrange.token_for(owner), body:, generation:)
  end

  # "While fenced, Timekeeping refuses every entry write at every generation with stale_generation, including for
  # a company it has never seen"
  it "refuses writes for an existing and a never-seen company alike while fenced and creates no state for either" do
    existing_company = timekeeping_arrange.company
    existing_owner = timekeeping_arrange.user(company: existing_company, role: "owner")
    timekeeping_arrange.entry(company: existing_company, user: existing_owner,
                              project: timekeeping_arrange.project(company: existing_company))
    Timekeeping::Admission.fence!(lock_timeout: 1)
    unseen_company = timekeeping_arrange.company
    expect(Entry.where(company_id: unseen_company).count).to eq(0)
    baseline = entry_write_counts
    expect(baseline[:entries]).to eq(1)

    [existing_company, unseen_company].product([1, 2]).each do |company, generation|
      outcome = described_class.new.call(fenced_create_for(company, generation:))

      expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, { "reason" => "stale_generation" }])
      expect(entry_write_counts).to eq(baseline)
    end

    expect(Timekeeping::Admission.count).to eq(1)
    expect(Timekeeping::Admission.current.generation).to be_nil
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "fence persistence" do
  include_context "timekeeping entry writes"

  # "The fence stays in place until a later admission"
  it "keeps refusing writes after a fence until admit! is called again" do
    company = timekeeping_arrange.company
    project = timekeeping_arrange.project(company:)
    token = timekeeping_arrange.token_for(timekeeping_arrange.user(company:, role: "owner"))
    body = { "project_id" => project, "work_date" => "2026-03-02", "duration" => 30.0, "note" => "Fence",
             "source" => "manual", "source_metadata" => {} }

    Timekeeping::Admission.fence!(lock_timeout: 1)
    before = entry_write_counts

    [1, 2, 1].each do |generation|
      outcome = described_class.new.call(build_entry_command(:create, token:, body:, generation:))
      expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, { "reason" => "stale_generation" }])
    end
    expect(Timekeeping::Admission.current.generation).to be_nil
    expect(entry_write_counts).to eq(before)

    Timekeeping::Admission.admit!(generation: 2)
    admitted = described_class.new.call(build_entry_command(:create, token:, body:, generation: 2))

    expect(admitted.status).to eq(201)
    expect(Timekeeping::Admission.current.generation).to eq(2)
  end
end
